import os
from model_client import get_bedrock_client


def stream_completion(payload, config=None):
    config = config or {}
    client = get_bedrock_client()

    prompt = payload["prompt"]

    stream_response = client.converse_stream(
        modelId=os.environ.get("BEDROCK_MODEL_ID", "anthropic.claude-3-sonnet-20240229-v1:0"),
        messages=[{"role": "user", "content": [{"text": prompt}]}],
        inferenceConfig={
            "maxTokens": config.get("max_tokens", 1000),
            "temperature": config.get("temperature", 0.7),
        },
    )

    for chunk in stream_response["stream"]:
        if "contentBlockDelta" in chunk and "text" in chunk["contentBlockDelta"]:
            yield {"token": chunk["contentBlockDelta"]["text"]}
        elif "messageStart" in chunk:
            yield {"status": "start"}
        elif "messageStop" in chunk:
            yield {"status": "stop", "stop_reason": chunk["messageStop"]["stopReason"]}

import boto3
import os


def translate_result(payload, config=None):
    config = config or {}
    aws_region = os.environ.get("AWS_REGION", "us-east-1")
    client = boto3.client("translate", region_name=aws_region)

    text_to_translate = payload["text"]
    target_language_code = payload.get("target_language", "en")
    source_language_code = payload.get("source_language", "auto")

    if source_language_code == "auto":
        response = client.translate_text(
            Text=text_to_translate,
            TargetLanguageCode=target_language_code
        )
    else:
        response = client.translate_text(
            Text=text_to_translate,
            SourceLanguageCode=source_language_code,
            TargetLanguageCode=target_language_code
        )

    translated_text = response["TranslatedText"]
    return {"translated_text": translated_text, "source_language": response.get("SourceLanguageCode"), "target_language": target_language_code}
